package com.example.paymentservicefeb25.models; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.Instant;
@Entity @Table(name="payment_idempotency",uniqueConstraints=@UniqueConstraint(name="uk_payment_idempotency",columnNames="idempotency_key")) @Getter @Setter public class PaymentIdempotency { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="idempotency_key",nullable=false,length=100) private String idempotencyKey; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="payment_id",nullable=true) private Long paymentId; @Column(nullable=false) private Instant createdAt; }
